"""Exact inverse of the reviewed r657 typed import; no other API bytes are masked.

Only the home recommendation historical-baseline guard imports this module.
The complete current import block must match once before restoring the frozen
HEAD block. Existing step8 and .552 assertions then run without any relaxation.
"""
import hashlib

REVIEWED_HEAD = 'fb660e769edfd0c892c48152b55c0d6f96a0b575'
REVIEWED_IMPORT = '    /** Import only a validated entity reference. Unknown URLs/shortlinks never reach the\n     * legacy text parser (which can return ok=true/type=lines with missing song IDs).\n     * Details keep their existing official-direct + same-provider server fallback policy.\n     */\n    suspend fun importPlaylist(raw: String): Playlist? {\n        // r658c D#3：分享短链先经有界白名单展开器换成可严格解析的长链（展开结果必然可解析，递归一层即止）。\n        if (xyz.cncnlp.soundwave.source.direct.parseOnlineImportReference(raw) == null) {\n            return xyz.cncnlp.soundwave.source.direct.OnlineImportShortLink.expand(raw)?.let { importPlaylist(it) }\n        }\n        val reference = xyz.cncnlp.soundwave.source.direct.parseOnlineImportReference(raw) ?: return null\n        val detail = xyz.cncnlp.soundwave.source.direct.canonicalizeImportDetail(when (reference.kind) {\n            xyz.cncnlp.soundwave.source.direct.OnlineImportKind.ALBUM -> albumDetail(reference.id, reference.source)\n            xyz.cncnlp.soundwave.source.direct.OnlineImportKind.PLAYLIST -> {\n                importOfficialPlaylistDirect(raw) ?: run {\n                    val seed = Playlist(id = reference.id, remoteId = reference.id,\n                        source = reference.source, name = "导入歌单", local = false)\n                    playlistDetailSnapshot(reference.id, reference.source, seed)\n                }\n            }\n        } ?: return null, reference.source)\n        // A nonempty response is not success: every retained row needs an actual same-source ID.\n        if (detail.source != reference.source) return null\n        val songs = detail.songs.filter { song -> song.id.isNotBlank() && song.source == reference.source }\n        if (songs.isEmpty()) return null\n        return detail.copy(id = reference.id, remoteId = reference.id, source = reference.source,\n            local = false, songs = songs.toMutableList(), count = maxOf(detail.count, songs.size))\n    }\n\n'
HEAD_IMPORT = '    /** 批17：playlistDetail 直连化后同步 suspend（实现不变；唯一调用点 MainActivity:3256 已在协程内）。 */\n    suspend fun importPlaylist(raw: String): Playlist? {\n        importOfficialPlaylistDirect(raw)?.let { return it }\n        // Shortlinks/commands and unavailable direct details keep the legacy parser route.\n        return try {\n            val q = raw.trim()\n            if (q.isEmpty()) return null\n            val src = when {\n                q.contains("netease", true) || q.contains("music.163") -> "wy"\n                q.contains("kugou", true) -> "kg"\n                q.contains("kuwo", true) -> "kw"\n                q.contains("y.qq") || q.contains("qq.com") -> "tx"\n                q.contains("migu", true) -> "mg"\n                else -> "wy"\n            }\n            // 优先 action=import（服务端多格式解析）\n            val enc = java.net.URLEncoder.encode(q, "UTF-8")\n            var rawDetail = get("/music/playlist?action=import&text=$enc")\n            if (rawDetail.isEmpty()) {\n                val idGuess = Regex("""[?&]id=([^&]+)""").find(q)?.groupValues?.getOrNull(1)\n                    ?: Regex("""(\\d{6,})""").find(q)?.groupValues?.getOrNull(1)\n                    ?: q\n                rawDetail = get("/music/playlist?action=detail&id=" + java.net.URLEncoder.encode(idGuess, "UTF-8") + "&source=$src")\n            }\n            if (rawDetail.isEmpty()) return null\n            val d = JSONObject(rawDetail)\n            // import 返回 ok=false\n            if (d.has("ok") && !d.optBoolean("ok", true)) return null\n            val name = orChain(d, "name", "nm").ifEmpty { "导入歌单" }\n            val author = d.optString("creator").ifBlank { d.optString("author") }.ifBlank {\n                d.optJSONObject("creator")?.optString("nickname").orEmpty()\n            }.ifBlank {\n                d.optJSONObject("author")?.optString("name").orEmpty()\n            }\n            var cover = normalizeCoverUrl(orChain(d, "cover", "pic"))\n            val type = d.optString("type")\n            val realSrc = when {\n                type.contains("netease", true) -> "wy"\n                else -> src\n            }\n            var songs = parseSongList(d.optJSONArray("list") ?: d.optJSONArray("songs"), realSrc)\n            if (songs.isEmpty()) {\n                val id = d.optString("id").ifEmpty {\n                    Regex("""(\\d{6,})""").find(q)?.groupValues?.getOrNull(1).orEmpty()\n                }\n                // 只在真实来源明确时重试详情；绝不回退网易云补数据。\n                if (id.isNotEmpty() && realSrc.isNotBlank()) songs = MusicSourceRegistry.platformSource(realSrc).playlistDetail(id)\n            }\n            if (songs.isEmpty()) return null\n            if (cover.isEmpty() && realSrc !in Platforms.ALL) cover = songs.firstOrNull()?.cover.orEmpty()\n            val id = d.optString("id").ifEmpty {\n                songs.firstOrNull()?.id?.let { "imp_$it" } ?: ("imp_" + System.currentTimeMillis())\n            }\n            Playlist(\n                id = id,\n                name = name.ifEmpty { "导入歌单" },\n                cover = cover,\n                songs = songs.toMutableList(),\n                local = false,\n                source = realSrc,\n                // 在线导入必须保留上游实际作者；缺字段由详情 UI 标为在线歌单，不伪造未知作者。\n                author = author\n            )\n        } catch (_: Exception) {\n            null\n        }\n    }\n'
PARSER_SHA256 = '55f511620d4aae2800fa68466124c786df280d02a4e31c9c3747343a02e91534'


def project_r657_home_import_api(text, parser_bytes):
    if text.count(REVIEWED_IMPORT) != 1:
        raise SystemExit("FAIL: missing/modified reviewed r657 typed import block")
    if hashlib.sha256(parser_bytes).hexdigest() != PARSER_SHA256:
        raise SystemExit("FAIL: reviewed r657 typed import parser changed")
    return text.replace(REVIEWED_IMPORT, HEAD_IMPORT, 1)
